// IA V2: there is no scheduled worker - a background completion or revert still waiting (a retry, a stock-lock wait, a parked
// second phase, a closed browser) moves on when this list opens (each worker at most every 2 minutes per browser). A worker
// whose switch is off (or whose id is not set): no call, no browser storage.
(() => {
  const ASYNC_IA_ENABLED = false;
  const ASYNC_IA_REVERT_ENABLED = false;
  const WORKERS = [
    { on: ASYNC_IA_ENABLED, key: "ia_v2_worker_kick_at", name: "IA V2",
      id: "2112141277456408577" }, // IA_V2_WORKER
    { on: ASYNC_IA_REVERT_ENABLED, key: "ia_rv_worker_kick_at", name: "IA Revert V2",
      id: "2112141417890095105" }, // IA_REVERT_V2_WORKER
  ];
  for (const worker of WORKERS) {
    if (worker.on !== true || !/^[1-9][0-9]{0,19}$/.test(worker.id)) continue;
    let last = 0;
    try {
      last = Number(localStorage.getItem(worker.key) || 0);
    } catch (e) {}
    if (Date.now() - last < 120000) continue;
    try {
      localStorage.setItem(worker.key, String(Date.now()));
    } catch (e) {}
    const tick = (round) => {
      try {
        const p = this.runWorkflow(
          worker.id,
          { job_id: "" },
          (w) => {
            const processed = Number((w && w.data && w.data.processed) || 0);
            if (processed > 0) {
              this.refresh();
              if (round < 40) tick(round + 1);
            }
          },
          (e) => console.error(worker.name + ": worker tick failed", e),
        );
        if (p && typeof p.catch === "function") p.catch(() => {});
      } catch (e) {
        console.error(worker.name + ": worker could not be started", e);
      }
    };
    tick(1);
  }
})();

(async () => {
  try {
    const row = arguments[0]?.row;
    if (!row || !row.id) {
      this.$message.error("No Item Assembly selected.");
      return;
    }

    const label = row.stock_movement_no || row.id;
    const status = row.item_assembly_status;

    // Once an assembly is completed the components have left stock and the
    // assembled item has been received; deleting the document would strand both.
    // A Processing one is being completed or reverted in the background.
    const UNDELETABLE = ["Completed", "Fully Posted", "Processing"];
    if (UNDELETABLE.includes(status)) {
      this.$message.error(
        `Item Assembly ${label} is ${status} and cannot be deleted.`
      );
      return;
    }

    // stock_movement_no is free text under the Manual Input serial rule, so it
    // cannot go into an HTML confirm unescaped.
    const escapeHtml = (value) =>
      String(value)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&#39;");

    await this.$confirm(
      `Delete Item Assembly <strong>${escapeHtml(
        label
      )}</strong>?<br>This cannot be undone.`,
      "Item Assembly Deletion",
      {
        confirmButtonText: "Delete",
        cancelButtonText: "Cancel",
        type: "warning",
        dangerouslyUseHTMLString: true,
      }
    ).catch(() => {
      throw new Error("cancelled");
    });

    // The grid can be stale (a background job may hold it now): the stored status decides.
    const storedRes = await db
      .collection("sm_item_assembly")
      .where({ id: row.id, is_deleted: 0 })
      .field("item_assembly_status")
      .get();
    const stored = (storedRes && storedRes.data && storedRes.data[0]) || null;
    if (!stored || UNDELETABLE.includes(stored.item_assembly_status)) {
      this.$message.error(
        stored
          ? `Item Assembly ${label} is ${stored.item_assembly_status} and cannot be deleted.`
          : `Item Assembly ${label} is no longer available.`
      );
      this.refresh();
      return;
    }

    await db
      .collection("sm_item_assembly")
      .doc(row.id)
      .update({ is_deleted: 1 });

    // Both subforms are real child tables; leaving them behind orphans them.
    const CHILD_TABLES = [
      "sm_item_assembly_tlm8ve69_sub",
      "sm_item_assembly_mw10kf66_sub",
    ];

    await Promise.all(
      CHILD_TABLES.map(async (table) => {
        const children = await db
          .collection(table)
          .where({ sm_item_assembly_id: row.id, is_deleted: 0 })
          .get()
          .catch(() => ({ data: [] }));

        await Promise.all(
          (children.data || []).map((child) =>
            db
              .collection(table)
              .doc(child.id)
              .update({ is_deleted: 1 })
              .catch((error) =>
                console.error(`Error deleting ${table} row:`, error)
              )
          )
        );
      })
    );

    this.refresh();
    this.$message.success(`Item Assembly ${label} deleted.`);
  } catch (error) {
    if (error?.message === "cancelled") return;
    console.error(error);
    this.$message.error(error?.message || "Failed to delete the Item Assembly");
  }
})();

// Bulk Revert Completed Item Assembly back to Draft.
//
// Everything is decided server-side: the workflow re-reads the record, so this
// only filters out rows the list already shows as ineligible.
//
// IA Revert V2: with ASYNC_IA_REVERT_ENABLED each assembly asks IA_REVERT_V2_SUBMIT first: more than 50 live stock rows ->
// reverted in the background by IA_REVERT_V2_WORKER (started here; the list's mounted starts it again); NOT_ELIGIBLE, INVALID
// or no usable answer -> the classic IA_REVERT below, unchanged.
const IA_REVERT_WORKFLOW_ID = "2099319746652852225";
const IARV_WF = {
  SUBMIT: "2112141384234999809", // IA_REVERT_V2_SUBMIT
  WORKER: "2112141417890095105", // IA_REVERT_V2_WORKER
};
// Switch: false = every assembly takes the classic revert
const ASYNC_IA_REVERT_ENABLED = false;
const IA_RV_MIN_ROWS = 50;
const IARV_KICK_MAX = 10;

const runRevertWorkflow = async (ia) => {
  return new Promise((resolve, reject) => {
    this.runWorkflow(
      IA_REVERT_WORKFLOW_ID,
      {
        ia_id: ia.id,
        ia_no: ia.stock_movement_no,
        organization_id: ia.organization_id,
      },
      (res) => resolve(res),
      (err) => reject(err),
    );
  });
};

const esc = (s) =>
  String(s === null || s === undefined ? "" : s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");

const handleWorkflowResult = (workflowResult, ia) => {
  const label = ia.stock_movement_no || ia.id;
  const fail = (error) => ({ label, success: false, error });

  if (!workflowResult || !workflowResult.data) {
    return fail("No response from revert workflow");
  }

  const data = workflowResult.data;
  const resultCode = String(data.code);
  const message = data.msg || data.message;

  // 409 - the assembled item has been used. Nothing was written.
  if (resultCode === "409") {
    const detail = Array.isArray(data.conflicts)
      ? data.conflicts
          .map((c) => c && c.message)
          .filter((m) => m)
          .join(" ")
      : "";
    return fail(
      [message || "The assembled item has already been used.", detail]
        .filter((m) => m)
        .join(" "),
    );
  }

  // 500 - the reversal stopped part way through and has to be run again.
  if (resultCode === "500") {
    return {
      label,
      success: false,
      partial: true,
      error: message || "Revert stopped part way through.",
    };
  }

  if (resultCode === "200") {
    return { label, success: true };
  }

  return fail(message || "Failed to revert Item Assembly");
};

const rvOn = () =>
  ASYNC_IA_REVERT_ENABLED === true && /^[1-9][0-9]{0,19}$/.test(IARV_WF.SUBMIT) && /^[1-9][0-9]{0,19}$/.test(IARV_WF.WORKER);
const str = (v) => (v === undefined || v === null ? "" : String(v)).trim();
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
// settles on the callback or on the promise runWorkflow returns, whichever comes first
const run = (id, params) =>
  new Promise((resolve, reject) => {
    const p = this.runWorkflow(id, params, (res) => resolve(res), (err) => reject(err));
    if (p && typeof p.then === "function") p.then((res) => resolve(res), (err) => reject(err));
  });

// one key per click and assembly: a lost answer re-sent with the same key finds the same job
const clickToken = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
const keyOf = (ia) => ("IAV:" + str(ia.organization_id) + ":" + str(ia.id) + ":" + clickToken).replace(/[^A-Za-z0-9|:_.-]/g, "-").slice(0, 128);
// RV4: every request key is sent (strings except form; the form is the list row)
const rvRequest = (ia, operation) => ({
  operation: operation,
  ia_id: str(ia.id),
  idempotency_key: keyOf(ia),
  source: "LIST",
  min_picks: String(IA_RV_MIN_ROWS),
  form:
    operation === "STATUS"
      ? {}
      : { id: str(ia.id), item_assembly_status: str(ia.item_assembly_status), stock_movement_no: str(ia.stock_movement_no), organization_id: str(ia.organization_id) },
});

const submitV2 = async (ia) => {
  const params = rvRequest(ia, "SUBMIT");
  let res = null;
  try {
    res = await run(IARV_WF.SUBMIT, params);
  } catch (e) {
    // the losing twin of the unique insert, a dropped connection: once more with the same key
    console.log("IA Revert V2: submit failed, repeating once with the same key", e);
    try {
      res = await run(IARV_WF.SUBMIT, params);
    } catch (again) {
      console.error("IA Revert V2: submit failed twice", again);
    }
  }
  return (res && res.data) || null;
};

const RV_OPEN = ["QUEUED", "VALIDATING", "READY_TO_COMMIT", "COMMITTING_REVERT"];
const watching = [];
const revertOne = async (ia) => {
  const label = ia.stock_movement_no || ia.id;
  const r = await submitV2(ia);
  // no usable answer, NOT_ELIGIBLE (50 live stock rows or fewer, handling units, ...) or INVALID: the classic revert
  if (!r || !r.route || r.route === "NOT_ELIGIBLE" || r.route === "INVALID") {
    return handleWorkflowResult(await runRevertWorkflow(ia), ia);
  }
  const js = str(r.job_status);
  if (r.route === "QUEUED" || (r.route === "STATUS" && RV_OPEN.indexOf(js) >= 0)) {
    watching.push(ia);
    return { label, success: true, queued: true };
  }
  if (r.route === "STATUS" && js === "COMPLETED") return { label, success: true };
  if (r.route === "STATUS" && (js === "FAILED" || js === "REQUIRES_REVIEW")) {
    return { label, success: false, error: str(r.error_message) || str(r.progress_message) || "The previous revert of this Item Assembly did not finish." };
  }
  return { label, success: false, error: str(r.message) || str(r.progress_message) || "Failed to revert Item Assembly" };
};

// the background revert finds the classic's conflicts (the assembled item used since, ...) only once it runs: say why
const reportFinished = async () => {
  const stopped = [];
  for (const ia of watching.splice(0)) {
    let r = {};
    try {
      const res = await run(IARV_WF.SUBMIT, rvRequest(ia, "STATUS"));
      r = (res && res.data) || {};
    } catch (e) {
      console.error("IA Revert V2: status check failed", e);
    }
    const js = str(r.job_status);
    if (js === "FAILED" || js === "REQUIRES_REVIEW") {
      stopped.push(`${esc(ia.stock_movement_no || ia.id)}: ${esc(str(r.error_message) || str(r.progress_message) || "The revert did not finish.")}`);
    } else if (js !== "COMPLETED") {
      watching.push(ia);
    }
  }
  if (stopped.length > 0) {
    await this.$alert(stopped.join("<br>"), "Revert did not finish", { type: "error", dangerouslyUseHTMLString: true }).catch(() => {});
  }
};

// no scheduled worker: driven here while it finds work (at most IARV_KICK_MAX calls), then by the list's mounted
const drainWorker = async () => {
  for (let n = 1; n <= IARV_KICK_MAX; n++) {
    let processed = 0;
    try {
      const res = await run(IARV_WF.WORKER, { job_id: "" });
      processed = Number((res && res.data && res.data.processed) || 0);
    } catch (e) {
      console.error("IA Revert V2: worker tick failed - the list starts it again", e);
    }
    this.refresh();
    if (watching.length > 0) await reportFinished();
    if (watching.length === 0) return;
    if (processed <= 0) await sleep(3000);
  }
};

(async () => {
  try {
    this.showLoading();

    const selectedRecords =
      this.getComponent("custom_7rq6zmn4")?.$refs.crud.tableSelect;

    if (!selectedRecords || selectedRecords.length === 0) {
      this.hideLoading();
      this.$message.error("Please select at least one record.");
      return;
    }

    const revertable = [];
    const skipped = [];
    for (const item of selectedRecords) {
      if (item.item_assembly_status === "Completed") {
        revertable.push(item);
      } else {
        skipped.push({
          label: item.stock_movement_no || item.id,
          success: false,
          error: `Only Completed Item Assembly can be reverted (this one is ${
            item.item_assembly_status || "blank"
          }).`,
        });
      }
    }

    const describe = (rows) =>
      rows.map((r) => `${esc(r.label)}: ${esc(r.error)}`).join("<br>");

    if (revertable.length === 0) {
      this.hideLoading();
      this.$message({
        type: "error",
        message: `None of the selected Item Assembly can be reverted.<br>${describe(
          skipped,
        )}`,
        dangerouslyUseHTMLString: true,
      });
      return;
    }

    const skippedNote =
      skipped.length > 0
        ? `<br><br><strong>${skipped.length} will be skipped:</strong><br>${describe(
            skipped,
          )}`
        : "";

    this.hideLoading();
    await this.$confirm(
      `You've selected ${
        revertable.length
      } Item Assembly to revert to Draft. This will take the assembled item back out of stock and return its components. Completing it again will issue a new number.<br><strong>Item Assembly Numbers:</strong><br>${revertable
        .map((item) => esc(item.stock_movement_no))
        .join(", ")}${skippedNote}<br><br>Do you want to proceed?`,
      "Revert Item Assembly to Draft",
      {
        confirmButtonText: "Revert",
        cancelButtonText: "Cancel",
        type: "warning",
        dangerouslyUseHTMLString: true,
      },
    ).catch(() => {
      throw new Error("cancelled");
    });

    this.showLoading("Reverting Item Assembly...");
    const results = skipped.slice();
    const v2 = rvOn();

    for (const ia of revertable) {
      try {
        results.push(v2 ? await revertOne(ia) : handleWorkflowResult(await runRevertWorkflow(ia), ia));
      } catch (error) {
        results.push({
          label: ia.stock_movement_no || ia.id,
          success: false,
          error: (error && error.message) || "Failed to revert",
        });
      }
    }

    this.hideLoading();

    // A half-finished reversal needs the user to act, so it gets its own alert.
    const partial = results.filter((r) => r.partial);
    if (partial.length > 0) {
      await this.$alert(describe(partial), "Revert did not finish", {
        type: "error",
        dangerouslyUseHTMLString: true,
      }).catch(() => {});
    }

    const queued = results.filter((r) => r.queued).length;
    const successCount = results.filter((r) => r.success && !r.queued).length;
    const failed = results.filter((r) => !r.success);
    const queuedNote = queued > 0 ? `${queued} being reverted in the background, ` : "";

    if (failed.length > 0) {
      this.$message({
        type: "error",
        message: `${successCount} reverted, ${queuedNote}${failed.length} failed:<br>${describe(
          failed,
        )}`,
        dangerouslyUseHTMLString: true,
      });
    } else if (queued > 0) {
      this.$message.success(
        `${queued} Item Assembly ${queued === 1 ? "is" : "are"} being reverted to Draft in the background` +
          (successCount > 0 ? `; ${successCount} reverted` : ""),
      );
    } else {
      this.$message.success(
        `All ${successCount} Item Assembly reverted to Draft successfully`,
      );
    }

    this.refresh();
    if (queued > 0) drainWorker();
  } catch (error) {
    this.hideLoading();
    if (error && error.message === "cancelled") return;
    console.error(error);
    this.$message.error((error && error.message) || "Failed to revert");
  }
})();

// Chunked reads with an explicit limit (the API clamps at IA_READ_MAX rows, as GDonMounted.js); a clamped read is read again
const IA_READ_CHUNK = 500;
const IA_READ_MAX = 5000;
const iaChunks = (list, size) => {
  const out = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
};
const iaUniq = (list) => [...new Set((list || []).filter((v) => v !== undefined && v !== null && v !== "").map(String))];

// rows of `collection` whose id is in `ids` (is_deleted 0), `fields` projected
const iaReadIds = async (collection, ids, fields) => {
  const rows = [];
  await Promise.all(
    iaChunks(iaUniq(ids), Math.min(IA_READ_CHUNK, IA_READ_MAX)).map(async (chunk) => {
      let left = chunk;
      while (left.length) {
        let got = [];
        try {
          let query = db.collection(collection);
          if (fields) query = query.field(fields);
          const res = await query
            .filter([
              {
                type: "branch",
                operator: "all",
                children: [
                  { prop: "id", operator: "in", value: left },
                  { prop: "is_deleted", operator: "equal", value: 0 },
                ],
              },
            ])
            .limit(left.length)
            .get();
          got = (res && res.data) || [];
        } catch (error) {
          console.error(`Error fetching ${collection}:`, error);
          return;
        }
        rows.push(...got);
        const seen = new Set(got.map((row) => String(row.id)));
        const missing = left.filter((id) => !seen.has(id));
        if (!got.length || missing.length === left.length) return;
        left = missing;
      }
    }),
  );
  return { data: rows };
};

// rows of `collection` whose `prop` is in `values`, with the other conditions
const iaReadMany = async (collection, prop, values, conditions) => {
  const rows = [];
  const read = async (chunk) => {
    let got = [];
    try {
      const res = await db
        .collection(collection)
        .filter([
          {
            type: "branch",
            operator: "all",
            children: [{ prop: prop, operator: "in", value: chunk }, ...conditions],
          },
        ])
        .limit(IA_READ_MAX)
        .get();
      got = (res && res.data) || [];
    } catch (error) {
      console.error(`Error fetching ${collection}:`, error);
      return;
    }
    if (got.length >= IA_READ_MAX && chunk.length > 1) {
      const half = Math.ceil(chunk.length / 2);
      await Promise.all([read(chunk.slice(0, half)), read(chunk.slice(half))]);
      return;
    }
    if (got.length >= IA_READ_MAX) console.error(`${collection}: more than ${IA_READ_MAX} rows for ${chunk[0]}; ${got.length} read`);
    rows.push(...got);
  };
  await Promise.all(iaChunks(iaUniq(values), IA_READ_CHUNK).map(read));
  return { data: rows };
};

const callPostItemAssemblyWorkflow = async (selectedRecords, aiData) => {
  switch (aiData.acc_integration_type) {
    case "SQL Accounting V2":
    case "AutoCount Accounting V2":
      await Promise.all(
        selectedRecords.map(async (item) => {
          await db
            .collection("sm_item_assembly")
            .doc(item.id)
            .update({ posted_status: "Pending Post" });
        }),
      );

      this.$message.success("Item assembly completed successfully.");
      this.refresh();
      this.hideLoading();
      await this.runWorkflow(
        "2013511169625042946",
        {
          agent_id: aiData.agent_id,
          task_type: "post_item_assembly",
          payload: selectedRecords.map((item) => item.id),
          priority: "0",
        },
        async (res) => {
          console.log("成功结果：", res);
        },
        (err) => {
          console.log("失败结果：", err);
        },
      );
      break;

    default:
      console.log(
        "No post handler for accounting integration type:",
        aiData.acc_integration_type,
      );
      break;
  }
};

(async () => {
  try {
    const allListID = "custom_7rq6zmn4";
    const organizationID = this.getVarGlobal("firstLvDeptId");
    this.showLoading("Posting Item Assembly...");

    let selectedRecords;

    selectedRecords = this.getComponent(allListID)?.$refs.crud.tableSelect;

    console.log("selectedRecords", selectedRecords);

    const getPostedStatus = (item) =>
      item.posted_status?.dict_key ?? item.posted_status;

    selectedRecords = selectedRecords.filter((item) => {
      if (item.item_assembly_status !== "Completed") {
        return false;
      }

      const postedStatus = getPostedStatus(item);
      return (
        postedStatus === "Unposted" ||
        postedStatus === "Failed Post" ||
        postedStatus === "" ||
        postedStatus === null ||
        postedStatus === undefined
      );
    });

    if (selectedRecords.length === 0) {
      this.hideLoading();
      await this.$alert(
        "No selected records are available for posting. Please select records with status 'Completed' and not yet posted.",
        "No Records to Post",
        {
          confirmButtonText: "OK",
          dangerouslyUseHTMLString: true,
          type: "warning",
        },
      );
      return;
    }

    // The grid can be stale (a background job may hold a row now, or it was posted since): the stored status decides.
    const [resAI, storedRes] = await Promise.all([
      db
        .collection("accounting_integration")
        .where({ organization_id: organizationID })
        .get(),
      iaReadIds(
        "sm_item_assembly",
        selectedRecords.map((item) => item.id),
        "item_assembly_status,posted_status",
      ),
    ]);
    const dictKey = (v) => String((v && typeof v === "object" ? v.dict_key : v) || "").trim();
    const stored = new Map((storedRes.data || []).map((row) => [String(row.id), row]));
    const postable = (item) => {
      const row = stored.get(String(item.id));
      return !!row && dictKey(row.item_assembly_status) === "Completed" && ["Unposted", "Failed Post", ""].indexOf(dictKey(row.posted_status)) >= 0;
    };
    const changed = selectedRecords.filter((item) => !postable(item));
    selectedRecords = selectedRecords.filter(postable);
    if (changed.length > 0) {
      const why = (item) => {
        const row = stored.get(String(item.id));
        return row ? [dictKey(row.item_assembly_status) || "no status", dictKey(row.posted_status)].filter((x) => x).join(", ") : "no longer available";
      };
      this.$message.warning(`Not posted, changed since the list loaded: ${changed.map((item) => `${item.stock_movement_no || item.id} (${why(item)})`).join("; ")}`);
    }
    if (selectedRecords.length === 0) {
      this.refresh();
      this.hideLoading();
      return;
    }

    if (resAI && resAI.data && resAI.data.length > 0) {
      const aiData = resAI.data[0];
      await callPostItemAssemblyWorkflow(selectedRecords, aiData);
    }

    await this.getComponent(allListID)?.$refs.crud.clearSelection();
    this.refresh();
    this.hideLoading();
  } catch (error) {
    console.error(error);
  }
})();

// Standard Item Assembly LIST toolbar > Print > JavaScript.
// Requires the dialogs and bindings described in README.md.
(async () => {
  try {
    const selected = this.getComponent("custom_7rq6zmn4")?.$refs?.crud?.tableSelect;
    if (!Array.isArray(selected) || !selected.length) {
      this.$message.error("Please select at least one Item Assembly.");
      return;
    }
    if (selected.some(row => typeof row.id !== "string" || !row.id)) {
      throw new Error("Item Assembly IDs must be non-empty strings.");
    }

    const plantId = String(this.getVarSystem("deptIds") || "").split(",")[0].trim();
    if (!plantId) throw new Error("Please select a plant first.");

    const result = await db.collection("print_template_access").filter([{
      type: "branch", operator: "all", children: [
        { prop: "plant_id", operator: "in", value: plantId },
        { prop: "doc_type", operator: "equal", value: "item_assembly" }
      ]
    }]).get();
    if (result?.success === false || !Array.isArray(result?.data)) {
      throw new Error("Could not load print templates.");
    }
    const plantIds = value => {
      if (typeof value === "string" && value.trim().startsWith("[")) {
        value = JSON.parse(value);
      }
      return (Array.isArray(value) ? value : String(value || "").split(","))
        .map(id => String(id?.id ?? id).trim());
    };
    // Fail closed if the service returns an out-of-scope access row.
    if (result.data.some(t => t.doc_type !== "item_assembly" ||
        !plantIds(t.plant_id).includes(plantId))) {
      throw new Error("Print template access returned an unexpected document type or plant.");
    }
    const templates = result.data.filter(t =>
      ["Template", "Label"].includes(t.template_type) &&
      typeof t.print_template_id === "string" && t.print_template_id
    );
    if (!templates.length) {
      this.$message.error("No Item Assembly print template found for this plant.");
      return;
    }

    await this.openDialog("dialog_print_template");
    this.setData({
      ia_print_ids: selected.map(row => row.id).join(","),
      ia_print_templates: templates,
      "dialog_print_template.print_template_id": "",
      "dialog_print_template.template_id": "",
      "dialog_print_template.type": ""
    });
    this.setOptionData("dialog_print_template.print_template_id", templates);
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "Unable to prepare Item Assembly printing.");
  }
})();

// dialog_print_template.print_template_id > onChange.
const template = arguments[0]?.fieldModel?.item;
this.setData({
  "dialog_print_template.template_id": template?.print_template_id || "",
  "dialog_print_template.type": template?.template_type || ""
});

// dialog_print_template > onConfirm.
(async () => {
  try {
    const accessId = this.getValue("dialog_print_template.print_template_id");
    const allowed = this.getValue("ia_print_templates");
    const template = Array.isArray(allowed) && allowed.find(t => t.id === accessId);
    if (!template) {
      this.$message.error("Please select a print template.");
      return;
    }
    const templateId = template.print_template_id;
    const ids = this.getValue("ia_print_ids");
    if (typeof ids !== "string" || !ids) throw new Error("Please select Item Assembly records again.");

    if (template.template_type === "Template") {
      const query = new URLSearchParams({ item_assembly_id: ids, name: "Item Assembly" });
      const tab = window.open(`/sucode/openpage/${encodeURIComponent(templateId)}?${query}`, "_blank");
      if (!tab) throw new Error("Please allow pop-ups and try again.");
      await this.closeDialog("dialog_print_template");
      return;
    }
    if (template.template_type !== "Label") throw new Error("Unsupported print template type.");

    const lines = [];
    for (const id of ids.split(",")) {
      // Load saved header fields; the list does not declare batch_no as a column.
      const result = await db.collection("sm_item_assembly").where({ id }).get();
      if (result?.success === false || !Array.isArray(result?.data) ||
          result.data.length !== 1 || result.data[0].id !== id) {
        throw new Error("Could not load the selected Item Assembly.");
      }
      const ia = result.data[0];
      if (String(ia.is_deleted ?? "0") !== "0") throw new Error("An Item Assembly was deleted. Please refresh.");
      const batch = String(ia.batch_no || "").trim();
      // Match MSR's batch-label policy, also excluding blank batch values.
      if (!batch || batch === "-") continue;
      const itemId = ia.item_id?.id ?? ia.item_id;
      if (typeof itemId !== "string" || !itemId) throw new Error("The assembled item ID could not be resolved.");
      lines.push({
        ia_id: id,
        ia_number: ia.stock_movement_no,
        item_id: itemId,
        item_name: ia.item_name,
        batch_no: batch,
        assembled_quantity: ia.item_qty,
        quantity: 1
      });
    }
    if (!lines.length) {
      this.$message.error("All selected Item Assembly records have no batch number.");
      return;
    }
    await this.openDialog("dialog_enter_qty");
    this.setData({
      "dialog_enter_qty.ia_line": lines,
      "dialog_enter_qty.selected_template_id": templateId
    });
    await this.closeDialog("dialog_print_template");
  } catch (error) {
    console.error(error);
    this.$message.error(error.message || "Unable to prepare printing.");
  }
})();

// dialog_enter_qty > onConfirm.
// PROPOSED ia_line/ia_id cache contract: verify workflow and label reader first.
(async () => {
  let printTab;
  try {
    const lines = this.getValue("dialog_enter_qty.ia_line");
    const templateId = this.getValue("dialog_enter_qty.selected_template_id");
    const ids = this.getValue("ia_print_ids");
    const templates = this.getValue("ia_print_templates");
    if (!Array.isArray(templates) || !templates.some(t =>
      t.print_template_id === templateId && t.template_type === "Label")) {
      throw new Error("Please select the label template again.");
    }
    if (!Array.isArray(lines) || !lines.length || !ids) throw new Error("No label data found.");
    if (lines.some(line => !Number.isSafeInteger(Number(line.quantity)) || Number(line.quantity) <= 0)) {
      throw new Error("Label quantity must be a positive whole number for every row.");
    }

    // Open during the click, before awaiting the workflow, to avoid popup blocking.
    printTab = window.open("about:blank", "_blank");
    if (!printTab) throw new Error("Please allow pop-ups and try again.");
    const userId = this.getVarSystem("uid");
    if (typeof userId !== "string" || !userId) throw new Error("Could not resolve the current user ID.");
    await new Promise((resolve, reject) => {
      this.runWorkflow("2009091613792018433", {
        data: {
          ia_line: JSON.stringify(lines.map(line => ({ ...line, quantity: Number(line.quantity) }))),
          ia_id: ids
        },
        template_id: templateId,
        user_id: userId
      }, result => {
        const body = result?.data ?? result;
        if (result?.success === false || body?.success === false ||
            (result?.code != null && String(result.code) !== "200") ||
            (body?.code != null && String(body.code) !== "200")) {
          reject(new Error(body?.msg || result?.msg || "Label preparation failed."));
        } else if (result == null) {
          reject(new Error("No response from the label workflow."));
        } else {
          resolve(result);
        }
      }, reject);
    });
    const query = new URLSearchParams({ template_id: templateId, name: "Item Assembly Label" });
    printTab.location.href = `/sucode/openpage/${encodeURIComponent(templateId)}?${query}`;
    await this.closeDialog("dialog_enter_qty");
  } catch (error) {
    if (printTab && !printTab.closed) printTab.close();
    console.error(error);
    this.$message.error(error?.message || "Unable to print Item Assembly labels.");
  }
})();
